def _network(code: str, message: str) -> NetworkError:
    return NetworkError(message, code=code)


def _json(body: Any) -> bytes:
    return json.dumps(body, separators=(",", ":"), ensure_ascii=False).encode()


def _parse(body: bytes, status: int = 200) -> Any:
    if not body:
        return None
    try:
        return json.loads(body)
    except ValueError as e:
        raise BackdError(
            "the answer is not the JSON expected: " + str(e), status=status, code="invalid_response"
        ) from e
